import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.kOe0DhAP.js";const p=JSON.parse('{"title":"核心设计","description":"币种、网络、地址和链上交易必须共同标识资产。","frontmatter":{"title":"核心设计","description":"币种、网络、地址和链上交易必须共同标识资产。"},"headers":[],"relativePath":"wallet/design.md","filePath":"wallet/design.md"}'),i={name:"wallet/design.md"};function d(n,a,s,l,c,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<div class="doc-eyebrow">钱包手册 / TGEX KNOWLEDGE BASE</div><h1 id="核心设计" tabindex="-1">核心设计 <a class="header-anchor" href="#核心设计" aria-label="Permalink to &quot;核心设计&quot;">​</a></h1><div class="doc-lead">币种、网络、地址和链上交易必须共同标识资产。</div><h2 id="network" tabindex="-1">币种与网络 <a class="header-anchor" href="#network" aria-label="Permalink to &quot;币种与网络 {#network}&quot;">​</a></h2><p>同一币种不同网络分别配置驱动、精度、确认要求和转账费用。代币还需要对应合约地址。不能只用币种简称识别链上资产。</p><h2 id="address" tabindex="-1">地址管理 <a class="header-anchor" href="#address" aria-label="Permalink to &quot;地址管理 {#address}&quot;">​</a></h2><p>地址分配需要绑定用户、商户、币种和网络；需要 Memo 或 Tag 的网络还应记录附加标识。地址校验应在提现发起前完成，展示时清晰标注网络。</p><h2 id="confirmations" tabindex="-1">交易与确认数 <a class="header-anchor" href="#confirmations" aria-label="Permalink to &quot;交易与确认数 {#confirmations}&quot;">​</a></h2><p>交易被广播、节点可查询、进入区块、达到确认要求是不同阶段。链上交易唯一性有时需要网络、交易哈希和事件序号等组合，不能假定一个交易哈希只包含一笔充值。</p><h2 id="ledger" tabindex="-1">钱包与内部账务 <a class="header-anchor" href="#ledger" aria-label="Permalink to &quot;钱包与内部账务 {#ledger}&quot;">​</a></h2><p>钱包记录证明链上动作，账务记录证明用户权益变化。充值监听重试必须识别既有入账，提现重试必须先确认已有交易是否发送，避免重复付款。</p>',11)])])}const m=e(i,[["render",d]]);export{p as __pageData,m as default};
